"""Editorial lessons and lazy prerequisite explanations for the attention example."""
from copy import deepcopy


def term(id, label, preview, reason):
    return dict(id=id, label=label, preview=preview, reason=reason)


def lesson(bridge, steps, takeaway, boundary, next_step):
    return dict(bridge=bridge, steps=[dict(title=a, text=b) for a, b in steps], takeaway=takeaway, boundary=boundary, next=next_step)


