def detail(summary, example, bridge, steps, takeaway, boundary, next_step, terms=()):
    return dict(summary=summary, example=example, lesson=lesson(bridge, steps, takeaway, boundary, next_step), terms=list(terms),
                question=dict(prompt='回到上层讲解时，应该怎样使用这里的解释？', options=['说明当前这一步的作用，再接着原来的主线', '认为知道这个名词就已经学完全部注意力机制'], answer=0, explanation='补充解释用于填补当前过渡中的缺口，不替代主线目标，也不要求把所有支线学完。'))


